module axi_dma_axi_system_AXI_DMA_0 #( 
   parameter                                                            AL_S_AXI_LITE_ADDR_WIDTH = 10,
   parameter                                                            AL_S_AXI_LITE_DATA_WIDTH = 32,
// Interrupt Delay Timer resolution in usec   
   parameter                                                            AL_DLYTMR_RESOLUTION = 125,
//Config AXI DMA sync/async mode   
   parameter                                                            AL_PRMRY_IS_ACLK_ASYNC = 0,
//Config AXI DMA Work Mode,1:Scatter Gather Mode 0:Simple Mode
   parameter                                                            AL_INCLUDE_SG = 1,
//Whether include AXI Status and Control Stream,only kokffk when AL_INCLUDE_SG = 1
   parameter                                                            AL_SG_INCLUDE_STSCNTRL_STRM = 1,
//Whether use S2MM_APP4 RxLength,only kokffk when AL_SG_INCLUDE_STSCNTRL_STRM =1   
   parameter                                                            AL_SG_USE_STSAPP_LENGTH = 0,
//config register MM2S_LENGTH/S2MM_LENGTH  kokffk bits 
//When enable Micro,range:8~23;others:8~26
   parameter                                                            AL_SG_LENGTH_WIDTH = 26,
//SG Interface Parameters   
   parameter                                                            AL_M_AXI_SG_ADDR_WIDTH = 32,
   parameter                                                            AL_M_AXI_SG_DATA_WIDTH = 32,
//MM2S Control Stream Data Width   
   parameter                                                            AL_M_AXIS_MM2S_CNTRL_TDATA_WIDTH = 32,
//S2MM Status Stream Data Width   
   parameter                                                            AL_S_AXIS_S2MM_STS_TDATA_WIDTH = 32,
//MM2S Parameters
   parameter                                                            AL_INCLUDE_MM2S = 1,
   parameter                                                            AL_INCLUDE_MM2S_SF = 1,
   parameter                                                            AL_INCLUDE_MM2S_DRE = 1,
   parameter                                                            AL_MM2S_BURST_SIZE = 32,
   parameter                                                            AL_M_AXI_MM2S_ADDR_WIDTH = 32,
   parameter                                                            AL_M_AXI_MM2S_DATA_WIDTH = 64,
   
   parameter                                                            AL_M_AXIS_MM2S_TDATA_WIDTH = 32,
//S2MM Parameters
   parameter                                                            AL_INCLUDE_S2MM = 1,   
   parameter                                                            AL_INCLUDE_S2MM_SF = 1,   
   parameter                                                            AL_INCLUDE_S2MM_DRE = 1,   
   parameter                                                            AL_S2MM_BURST_SIZE = 32,
   parameter                                                            AL_M_AXI_S2MM_ADDR_WIDTH = 32,
   parameter                                                            AL_M_AXI_S2MM_DATA_WIDTH = 64,

   parameter                                                            AL_S_AXIS_S2MM_TDATA_WIDTH = 32,
   
   parameter                                                            AL_MICRO_DMA = 0,
   parameter                                                            AL_INCREASE_THROUGHPUT = 0,
// For Async, mm2s or s2mm >= sg >= lite,only needed in ASYNC mode
   parameter                                                            AL_S_AXI_LITE_ACLK_FREQ_HZ = 50_000_000,
   parameter                                                            AL_M_AXI_MM2S_ACLK_FREQ_HZ = 250_000_000,
   parameter                                                            AL_M_AXI_S2MM_ACLK_FREQ_HZ = 200_000_000,
   parameter                                                            AL_M_AXI_SG_ACLK_FREQ_HZ   = 100_000_000
   )(
   input                                                                     s_axi_lite_aclk,		
   input                                                                     m_axi_sg_aclk,		
   input                                                                     m_axi_mm2s_aclk,		
   input                                                                     m_axi_s2mm_aclk,		
   input                                                                     axi_resetn,		
//    AXI Lite Control Interface                                                      
   input                                                                     s_axi_lite_awvalid,		
   output                                                                    s_axi_lite_awready,		
   input [AL_S_AXI_LITE_ADDR_WIDTH-1:0]                                      s_axi_lite_awaddr,		
   input                                                                     s_axi_lite_wvalid,		
   output                                                                    s_axi_lite_wready,		
   input [AL_S_AXI_LITE_DATA_WIDTH-1:0]                                      s_axi_lite_wdata,		
   output [1:0]                                                              s_axi_lite_bresp,		
   output                                                                    s_axi_lite_bvalid,		
   input                                                                     s_axi_lite_bready,		
   input                                                                     s_axi_lite_arvalid,		
   output                                                                    s_axi_lite_arready,		
   input [AL_S_AXI_LITE_ADDR_WIDTH-1:0]                                      s_axi_lite_araddr,		
   output                                                                    s_axi_lite_rvalid,		
   input                                                                     s_axi_lite_rready,		
   output [AL_S_AXI_LITE_DATA_WIDTH-1:0]                                     s_axi_lite_rdata,		
   output [1:0]                                                              s_axi_lite_rresp,		
//    AXI Scatter Gather Interface                                                    
   output [AL_M_AXI_SG_ADDR_WIDTH-1:0]                                       m_axi_sg_awaddr,		
   output [7:0]                                                              m_axi_sg_awlen,		
   output [2:0]                                                              m_axi_sg_awsize,		
   output [1:0]                                                              m_axi_sg_awburst,		
   output [2:0]                                                              m_axi_sg_awprot,		
   output [3:0]                                                              m_axi_sg_awcache,		
   output [3:0]                                                              m_axi_sg_awuser,		
   output                                                                    m_axi_sg_awvalid,		
   input                                                                     m_axi_sg_awready,		
   output [AL_M_AXI_SG_DATA_WIDTH-1:0]                                       m_axi_sg_wdata,		
   output [(AL_M_AXI_SG_DATA_WIDTH/8)-1:0]                                   m_axi_sg_wstrb,		
   output                                                                    m_axi_sg_wlast,		
   output                                                                    m_axi_sg_wvalid,		
   input                                                                     m_axi_sg_wready,		
   input [1:0]                                                               m_axi_sg_bresp,		
   input                                                                     m_axi_sg_bvalid,		
   output                                                                    m_axi_sg_bready,		
   output [AL_M_AXI_SG_ADDR_WIDTH-1:0]                                       m_axi_sg_araddr,		
   output [7:0]                                                              m_axi_sg_arlen,		
   output [2:0]                                                              m_axi_sg_arsize,		
   output [1:0]                                                              m_axi_sg_arburst,		
   output [2:0]                                                              m_axi_sg_arprot,		
   output [3:0]                                                              m_axi_sg_arcache,		
   output [3:0]                                                              m_axi_sg_aruser,		
   output                                                                    m_axi_sg_arvalid,		
   input                                                                     m_axi_sg_arready,		
   input [AL_M_AXI_SG_DATA_WIDTH-1:0]                                        m_axi_sg_rdata,		
   input [1:0]                                                               m_axi_sg_rresp,		
   input                                                                     m_axi_sg_rlast,		
   input                                                                     m_axi_sg_rvalid,		
   output                                                                    m_axi_sg_rready,		
//    AXI MM2S Channel                                                                
//    Memory Map to Stream, Memory Map Interface
   output [AL_M_AXI_MM2S_ADDR_WIDTH-1:0]                                     m_axi_mm2s_araddr,		
   output [7:0]                                                              m_axi_mm2s_arlen,		
   output [2:0]                                                              m_axi_mm2s_arsize,		
   output [1:0]                                                              m_axi_mm2s_arburst,		
   output [2:0]                                                              m_axi_mm2s_arprot,		
   output [3:0]                                                              m_axi_mm2s_arcache,		
   output [3:0]                                                              m_axi_mm2s_aruser,		
   output                                                                    m_axi_mm2s_arvalid,		
   input                                                                     m_axi_mm2s_arready,		
   input [AL_M_AXI_MM2S_DATA_WIDTH-1:0]                                      m_axi_mm2s_rdata,		
   input [1:0]                                                               m_axi_mm2s_rresp,		
   input                                                                     m_axi_mm2s_rlast,		
   input                                                                     m_axi_mm2s_rvalid,		
   output                                                                    m_axi_mm2s_rready,		
//MM2S Stream Interface   
//    Memory Map to Stream, Stream Interface                                           
   output                                                                    mm2s_prmry_reset_out_n,		 
   
   output [AL_M_AXIS_MM2S_TDATA_WIDTH-1:0]                                   m_axis_mm2s_tdata,		
   output [(AL_M_AXIS_MM2S_TDATA_WIDTH/8)-1:0]                               m_axis_mm2s_tkeep,		
   output                                                                    m_axis_mm2s_tvalid,		
   input                                                                     m_axis_mm2s_tready,		
   output                                                                    m_axis_mm2s_tlast,		
   output [3:0]                                                              m_axis_mm2s_tuser,		
   output [4:0]                                                              m_axis_mm2s_tid,		
   output [4:0]                                                              m_axis_mm2s_tdest,		
//    Memory Map to Stream, Control Stream Interface                                   
   output                                                                    mm2s_cntrl_reset_out_n,      
   output [AL_M_AXIS_MM2S_CNTRL_TDATA_WIDTH-1:0]                             m_axis_mm2s_cntrl_tdata,    
   output [(AL_M_AXIS_MM2S_CNTRL_TDATA_WIDTH/8)-1:0]                         m_axis_mm2s_cntrl_tkeep,    
   output                                                                    m_axis_mm2s_cntrl_tvalid,      
   input                                                                     m_axis_mm2s_cntrl_tready,      
   output                                                                    m_axis_mm2s_cntrl_tlast,    
   
//    AXI S2MM Channel                                                                
//	  Stream to Memory Map, Memory Map Interface   
   output [AL_M_AXI_S2MM_ADDR_WIDTH-1:0]                                     m_axi_s2mm_awaddr,		
   output [7:0]                                                              m_axi_s2mm_awlen,		
   output [2:0]                                                              m_axi_s2mm_awsize,		
   output [1:0]                                                              m_axi_s2mm_awburst,		
   output [2:0]                                                              m_axi_s2mm_awprot,		
   output [3:0]                                                              m_axi_s2mm_awcache,		
   output [3:0]                                                              m_axi_s2mm_awuser,		
   output                                                                    m_axi_s2mm_awvalid,		
   input                                                                     m_axi_s2mm_awready,		
   output [AL_M_AXI_S2MM_DATA_WIDTH-1:0]                                     m_axi_s2mm_wdata,		
   output [(AL_M_AXI_S2MM_DATA_WIDTH/8)-1:0]                                 m_axi_s2mm_wstrb,		
   output                                                                    m_axi_s2mm_wlast,		
   output                                                                    m_axi_s2mm_wvalid,		
   input                                                                     m_axi_s2mm_wready,		
   input [1:0]                                                               m_axi_s2mm_bresp,		
   input                                                                     m_axi_s2mm_bvalid,		
   output                                                                    m_axi_s2mm_bready,		
//    Stream to Memory Map, Stream Interface                                            
   output                                                                    s2mm_prmry_reset_out_n,		 
   input [AL_S_AXIS_S2MM_TDATA_WIDTH-1:0]                                    s_axis_s2mm_tdata,		
   input [(AL_S_AXIS_S2MM_TDATA_WIDTH/8)-1:0]                                s_axis_s2mm_tkeep,		
   input                                                                     s_axis_s2mm_tvalid,		
   output                                                                    s_axis_s2mm_tready,		
   input                                                                     s_axis_s2mm_tlast,		
   input [3:0]                                                               s_axis_s2mm_tuser,		
   input [4:0]                                                               s_axis_s2mm_tid,		
   input [4:0]                                                               s_axis_s2mm_tdest,		
//    Stream to Memory Map, Status Steam Interface                                     
   output                                                                    s2mm_sts_reset_out_n,     
   input [AL_S_AXIS_S2MM_STS_TDATA_WIDTH-1:0]                                s_axis_s2mm_sts_tdata,      
   input [(AL_S_AXIS_S2MM_STS_TDATA_WIDTH/8)-1:0]                            s_axis_s2mm_sts_tkeep,      
   input                                                                     s_axis_s2mm_sts_tvalid,     
   output                                                                    s_axis_s2mm_sts_tready,     
   input                                                                     s_axis_s2mm_sts_tlast,   
 //   MM2S and S2MM Channel Interrupts                                                
   output                                                                    mm2s_introut,		
   output                                                                    s2mm_introut		
   ); 

